"""Reusable column sets shared by ORM models (see ADR 0003)."""

import uuid
from datetime import datetime

from sqlalchemy import Boolean, DateTime, FetchedValue, String, func, text
from sqlalchemy.orm import Mapped, mapped_column


class UUIDPrimaryKeyMixin:
    """UUID primary key generated by PostgreSQL."""

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True, server_default=text("gen_random_uuid()")
    )


class TimestampMixin:
    """`created_at` / `updated_at`; `updated_at` is maintained by the `set_updated_at` trigger."""

    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        server_default=func.now(),
        # The database trigger changes this column; tell the ORM to re-fetch it after updates.
        server_onupdate=FetchedValue(),
    )


class LocalizedNameMixin:
    """Names in English (required), Marathi (required) and Hindi (optional)."""

    name_en: Mapped[str] = mapped_column(String(200))
    name_mr: Mapped[str] = mapped_column(String(200))
    name_hi: Mapped[str | None] = mapped_column(String(200))


class ActiveMixin:
    """Soft-disable flag for reference data: hidden from users but still referenceable."""

    is_active: Mapped[bool] = mapped_column(Boolean, server_default=text("true"))


SLUG_PATTERN = r"^[a-z0-9]+(-[a-z0-9]+)*$"
SLUG_MAX_LENGTH = 100
slug_column_type = String(SLUG_MAX_LENGTH)
